  ccBridgeTransforms: z
    .object({
      enabled: z.boolean(),
      pipeline: z
        .array(z.discriminatedUnion("kind", commonSystemTransformOperationSchemas))
        .max(50),
    })
    .optional(),
  // System Transforms (issue #2260 v2): generic per-provider DSL covering
