        .max(600000, "Must be at most 600,000ms (10 min)")
        .optional(),
      maxCooldownMs: z
        .number()
        .int()
        .min(5000, "Must be at least 5,000ms")
        .max(3600000, "Must be at most 3,600,000ms (1 h)")
